// SAM v2 strict-profile spec of src/host.impl.ts: the lease service, clients c0/c1,
// and the network. The network is the multiset of messages in transit, kept as an
// array sorted canonically (message ids are not modeled), so `deliver({ i })`
// delivers the i-th message of that order.
'use strict';
const { createInstance } = require('sam-pattern');

const CLIENTS = ['c0', 'c1'];
const SERVICE = 'lease';
const MAX_GRANTS = 2;
const MAX_WRITES = 2;
// At most 8 messages are ever in transit (a request or its answer and a write or its
// answer per client, plus at most 2 Releases and 2 Revokeds); indices 0..8 go one
// past that bound so an overflow would show up as a network-bounded violation.
const MAX_NET = 9;

const IDLE_CLIENT = { status: 'idle', token: 0, writing: false, revoked: 0 };
const INITIAL_STATE = { holder: null, token: 0, writes: 0, c0: { ...IDLE_CLIENT }, c1: { ...IDLE_CLIENT }, net: [] };

const instance = createInstance({ strict: true, hasAsyncActions: false });

const modelShape = {
  holder: { type: 'string', nullable: true },
  token: { type: 'number' },
  writes: { type: 'number' },
  c0: { type: 'object' },
  c1: { type: 'object' },
  net: { type: 'array' },
};

const msg = (from, to, action, data) => ({ from, to, action, data });
const key = (m) => JSON.stringify([m.to, m.action, m.from, m.data.from ?? null, m.data.token ?? null]);
const withMsg = (net, m) => [...net, m].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
const without = (net, i) => net.filter((_, j) => j !== i);
const isClient = (c) => CLIENTS.includes(c);

const clientSchema = { client: { type: 'string', required: true } };
const clientDomain = [{ client: 'c0' }, { client: 'c1' }, { client: 'c2' }];
const actions = {
  acquire: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  release: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  write: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  expire: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
  deliver: {
    action: (data = {}) => ({ ...data }),
    schema: { i: { type: 'number', required: true } },
    domain: Array.from({ length: MAX_NET }, (_, i) => ({ i })),
  },
};

const acceptors = {
  acquire: (model) => ({ client }, { reject, next, unchanged }) => {
    if (!isClient(client)) return reject('unknown client');
    if (model[client].status !== 'idle') return reject('client not idle');
    next[client] = { ...model[client], status: 'requesting' };
    next.net = withMsg(model.net, msg(client, SERVICE, 'Acquire', { from: client }));
    unchanged('*');
  },

  release: (model) => ({ client }, { reject, next, unchanged }) => {
    if (!isClient(client)) return reject('unknown client');
    const c = model[client];
    if (c.status !== 'holding') return reject('client does not hold the lease');
    next[client] = { ...c, status: 'idle' };
    next.net = withMsg(model.net, msg(client, SERVICE, 'Release', { from: client, token: c.token }));
    unchanged('*');
  },

  write: (model) => ({ client }, { reject, next, unchanged }) => {
    if (!isClient(client)) return reject('unknown client');
    const c = model[client];
    if (c.status !== 'holding') return reject('client does not hold the lease');
    if (c.writing) return reject('write waiting for an answer');
    next[client] = { ...c, writing: true };
    next.net = withMsg(model.net, msg(client, SERVICE, 'Write', { from: client, token: c.token }));
    unchanged('*');
  },

  expire: (model) => (_p, { reject, next, unchanged }) => {
    if (model.holder === null) return reject('no client holds the lease');
    next.holder = null;
    next.net = withMsg(model.net, msg(SERVICE, model.holder, 'Revoked', { token: model.token }));
    unchanged('*');
  },

  deliver: (model) => ({ i }, { reject, next, unchanged }) => {
    if (!(i >= 0 && i < model.net.length)) return reject('no such message');
    const m = model.net[i];
    const rest = without(model.net, i);

    if (m.to === SERVICE) {
      const from = m.data.from;
      const current = model.holder !== null && model.holder === from && m.data.token === model.token;
      if (m.action === 'Acquire') {
        if (model.holder === null && model.token < MAX_GRANTS) {
          const token = model.token + 1;
          next.token = token;
