  assert.equal((await h.lease()).writes, 1);
  // a new grant allows a new write
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  await h.write('c1');
  await h.deliver((await find(h, 'Write')).id);
  assert.ok(await find(h, 'WriteDone', 'c1'));
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 2 });
});

test('a refused stale write does not use up the new grant', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0');
  await h.expire(); await h.deliver((await find(h, 'Revoked')).id);
  await h.acquire('c1'); await h.deliver((await find(h, 'Acquire')).id);
  await h.deliver((await find(h, 'Write')).id); // stale token 1
  assert.ok(await find(h, 'WriteRefused', 'c0'));
  await h.deliverAll();
  await h.write('c1'); await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 1 });
});

test('stale release is ignored', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.release('c0');
  const rel = await find(h, 'Release');
  await h.expire().catch(() => {});
  // service still has c0 as holder until Release arrives: expire it, then grant c1
  await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.equal((await h.lease()).holder, 'c1');
  assert.ok(rel);
});

test('random schedules keep the invariants', async () => {
  let seed = 7;
  const rnd = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 400; run++) {
    const h = await createHost();
    for (let step = 0; step < 40; step++) {
      const k = rnd(6);
      const c = rnd(2) ? 'c0' : 'c1';
      const before = await h.lease();
      if (k === 0) await h.acquire(c);
      else if (k === 1) await h.release(c);
      else if (k === 2) await h.write(c);
      else if (k === 3) await h.expire();
      else {
        const f = await h.inFlight();
        if (f.length) {
          const m = f[rnd(f.length)];
          await h.deliver(m.id);
          const after = await h.lease();
          if (m.action === 'Write' && after.writes > before.writes) {
            assert.equal(m.data.from, before.holder);
            assert.equal(m.data.token, before.token);
          }
        }
      }
      const holders = [];
      for (const id of ['c0', 'c1']) {
        const v = await h.client(id);
        if (v.status === 'holding' && v.token === (await h.lease()).token) holders.push(id);
      }
      assert.ok(holders.length <= 1);
    }
    await h.deliverAll();
    const l = await h.lease();
    for (const id of ['c0', 'c1']) {
      assert.equal((await h.client(id)).status === 'holding', l.holder === id, `run ${run}`);
    }
  }
});

