    if (c.status !== 'holding') return reject('client does not hold the lease');
    next[client] = { ...c, status: 'idle' };
    next.net = withMsg(model.net, msg(client, SERVICE, 'Release', { from: client, token: c.token }));
    unchanged('*');
  },

  write: (model) => ({ client }, { reject, next, unchanged }) => {
    if (!isClient(client)) return reject('unknown client');
    const c = model[client];
    if (c.status !== 'holding') return reject('client does not hold the lease');
    if (c.writing) return reject('write waiting for an answer');
    next[client] = { ...c, writing: true };
    next.net = withMsg(model.net, msg(client, SERVICE, 'Write', { from: client, token: c.token }));
    unchanged('*');
  },

  expire: (model) => (_p, { reject, next, unchanged }) => {
    if (model.holder === null) return reject('no client holds the lease');
    next.holder = null;
    next.net = withMsg(model.net, msg(SERVICE, model.holder, 'Revoked', { token: model.token }));
    unchanged('*');
  },

  deliver: (model) => ({ i }, { reject, next, unchanged }) => {
    if (!(i >= 0 && i < model.net.length)) return reject('no such message');
    const m = model.net[i];
    const rest = without(model.net, i);

    if (m.to === SERVICE) {
      const from = m.data.from;
      const current = model.holder !== null && model.holder === from && m.data.token === model.token;
      if (m.action === 'Acquire') {
        if (model.holder === null && model.token < MAX_GRANTS) {
          const token = model.token + 1;
          next.token = token;
          next.holder = from;
          next.wrote = false;
          next.net = withMsg(rest, msg(SERVICE, from, 'Granted', { token }));
        } else {
          next.net = withMsg(rest, msg(SERVICE, from, 'Denied', {}));
        }
      } else if (m.action === 'Release') {
        if (current) next.holder = null;
        next.net = rest;
      } else if (m.action === 'Write') {
        if (current && model.writes < MAX_WRITES) {
          next.writes = model.writes + 1;
          next.net = withMsg(rest, msg(SERVICE, from, 'WriteDone', {}));
        } else {
          next.net = withMsg(rest, msg(SERVICE, from, 'WriteRefused', {}));
        }
      }
      unchanged('*');
      return;
    }

    const name = m.to;
    const c = model[name];
    const t = m.data.token;
    let nc = c;
    if (m.action === 'Granted') {
      if (c.status === 'requesting') nc = { ...c, token: t, status: t <= c.revoked ? 'idle' : 'holding' };
    } else if (m.action === 'Denied') {
      if (c.status === 'requesting') nc = { ...c, status: 'idle' };
    } else if (m.action === 'Revoked') {
      if (c.status === 'holding') {
        if (t === c.token) nc = { ...c, status: 'idle' };
      } else if (t > c.revoked) {
        nc = { ...c, revoked: t };
      }
    } else if (m.action === 'WriteDone' || m.action === 'WriteRefused') {
      nc = { ...c, writing: false };
    }
    next[name] = nc;
    next.net = rest;
    unchanged('*');
  },
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

const init = () => setState(INITIAL_STATE);
const getState = () => instance({}).getState();
const setState = (snapshot) => instance({}).setState(snapshot);

const exported = {};
for (const a of Object.keys(actions)) exported[a] = (data = {}) => intents[a](data);

module.exports = { instance, init, actions: exported, getState, setState, MAX_NET };

// Captures NDJSON trace windows {pre, action, data, post} from src/host.impl.ts,
// in the shape of spec/lease.cjs: in-flight messages without ids, sorted
// canonically, and `deliver({ i })` naming the i-th message of that order.
// Usage: node spec/capture.mjs [outDir]
import { mkdirSync, writeFileSync } from 'node:fs';
import { createSystem } from '../src/host.impl.ts';

const outDir = process.argv[2] ?? 'spec/traces';
mkdirSync(outDir, { recursive: true });

const key = (m) => JSON.stringify([m.to, m.action, m.from, m.data.from ?? null, m.data.token ?? null]);
const sortedNet = (net) => [...net].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));

function snapshot(sys) {
  const s = sys.state;
  const net = sortedNet(s.net).map(({ from, to, action, data }) => ({ from, to, action, data: { ...data } }));
  return { holder: s.service.holder, token: s.service.token, writes: s.service.writes, c0: { ...s.clients.c0 }, c1: { ...s.clients.c1 }, net };
}

function step(sys, windows, action, data) {
  const pre = snapshot(sys);
  if (action === 'deliver') {
    const m = sortedNet(sys.state.net)[data.i];
    if (m) sys.deliver(m.id);
  } else if (action === 'expire') sys.expire();
  else sys[action](data.client);
  windows.push({ pre, action, data, post: snapshot(sys) });
}

const save = (name, windows) => writeFileSync(`${outDir}/${name}.ndjson`, windows.map((w) => JSON.stringify(w)).join('\n') + '\n');

// Scripted scenarios.
const scripted = {
  happy: [['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['release', 'c0'], ['deliver', 0]],
  revokedBeforeGranted: [['acquire', 'c0'], ['deliver', 0], ['expire'], ['deliver', 1], ['deliver', 0], ['acquire', 'c0'], ['deliver', 0], ['deliver', 0]],
  staleWrite: [['acquire', 'c1'], ['deliver', 0], ['deliver', 0], ['write', 'c1'], ['expire'], ['deliver', 1], ['deliver', 0], ['deliver', 0], ['write', 'c1']],
  limits: [['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0],
    ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['release', 'c0'], ['deliver', 0], ['acquire', 'c1'], ['deliver', 0], ['deliver', 0], ['release', 'c1'], ['deliver', 0],
    ['acquire', 'c0'], ['deliver', 0], ['deliver', 0]],
  refusals: [['acquire', 'c2'], ['release', 'c0'], ['write', 'c0'], ['expire'], ['deliver', 3], ['acquire', 'c0'], ['acquire', 'c0'], ['deliver', 0], ['acquire', 'c1'], ['deliver', 1], ['deliver', 0], ['deliver', 0]],
};
for (const [name, cmds] of Object.entries(scripted)) {
  const sys = createSystem();
  const windows = [];
  for (const [action, arg] of cmds) {
    const data = action === 'deliver' ? { i: arg } : action === 'expire' ? {} : { client: arg };
    step(sys, windows, action, data);
  }
  save(name, windows);
}

// Random schedules (deterministic LCG).
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
for (let run = 0; run < 40; run++) {
  const sys = createSystem();
  const windows = [];
  for (let k = 0; k < 40; k++) {
    const r = rnd(10);
    const client = ['c0', 'c1', 'c0', 'c1', 'c2'][rnd(5)];
    if (r === 0) step(sys, windows, 'acquire', { client });
    else if (r === 1) step(sys, windows, 'release', { client });
    else if (r === 2) step(sys, windows, 'write', { client });
    else if (r === 3) step(sys, windows, 'expire', {});
    else step(sys, windows, 'deliver', { i: rnd(Math.max(1, sys.state.net.length + (r === 9 ? 1 : 0))) });
  }
  save(`random-${String(run).padStart(2, '0')}`, windows);
}
console.log(`traces written to ${outDir}`);

