// SAM v2 strict-profile spec of src/host.impl.ts: the lease service, clients c0/c1,
// and the network. The network is the multiset of messages in transit, kept as an
// array sorted canonically (message ids are not modeled), so `deliver({ i })`
// delivers the i-th message of that order.
'use strict';
// The vendored bundle by path (the same file polygraph pins 'sam-pattern' to), so the
// spec/model/lease.js shim the replayer loads resolves the same library instance.
const { createInstance } = require('../tools/polygraph/scripts/vendor/sam-pattern.cjs');

const CLIENTS = ['c0', 'c1'];
const SERVICE = 'lease';
const MAX_GRANTS = 2;
const MAX_WRITES = 2;
// At most 8 messages are ever in transit (a request or its answer and a write or its
// answer per client, plus at most 2 Releases and 2 Revokeds); indices 0..8 go one
// past that bound so an overflow would show up as a network-bounded violation.
const MAX_NET = 9;

const IDLE_CLIENT = { status: 'idle', token: 0, writing: false, revoked: 0 };
const INITIAL_STATE = { holder: null, token: 0, writes: 0, wrote: false, c0: { ...IDLE_CLIENT }, c1: { ...IDLE_CLIENT }, net: [] };

const instance = createInstance({ strict: true, hasAsyncActions: false });

const modelShape = {
  holder: { type: 'string', nullable: true },
  token: { type: 'number' },
  writes: { type: 'number' },
  wrote: { type: 'boolean' }, // a write was taken since the last grant
  c0: { type: 'object' },
  c1: { type: 'object' },
  net: { type: 'array' },
};

