    { "name": "write-limit", "note": "At most 2 writes taken; further writes are WriteRefused." },
    { "name": "one-write-per-grant", "note": "A write from the current holder is taken only if no write was taken since the last grant (wrote is reset on each grant); otherwise WriteRefused." }
  ],
  "noOpRule": "A refused command or an out-of-range deliver index leaves the state unchanged (reject(reason))."
