import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const find = async (h, action, to) => (await h.inFlight()).find((m) => m.action === action && (!to || m.to === to));

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c2'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('unknown clients are refused', async () => {
  const h = await createHost();
  for (const cmd of ['acquire', 'release', 'write']) assert.equal((await h[cmd]('x')).ok, false);
  assert.equal((await h.expire()).ok, false);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.acquire('c0')).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } });
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  const w = await find(h, 'Write');
  assert.deepEqual(w.data, { from: 'c0', token: 1 });
  await h.deliver(w.id);
  assert.equal((await find(h, 'WriteDone', 'c0')).from, 'lease');
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.equal((await h.lease()).writes, 1);
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.deepEqual((await find(h, 'Release')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  assert.equal((await h.client('c0')).status, 'idle');
});

test('denied while held, and after two grants', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'idle', token: 0, writing: false });
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.equal((await h.client('c1')).token, 2);
  await h.release('c1'); await h.deliverAll();
  await h.acquire('c0');
  const a = await find(h, 'Acquire');
  await h.deliver(a.id);
  assert.ok(await find(h, 'Denied', 'c0'));
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('expire revokes; stale write refused', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0');
  assert.deepEqual(await h.expire(), { ok: true });
  assert.equal((await h.expire()).ok, false);
  const r = await find(h, 'Revoked', 'c0');
  assert.deepEqual(r.data, { token: 1 });
  const w = await find(h, 'Write');
  await h.deliver(w.id);
  assert.ok(await find(h, 'WriteRefused', 'c0'));
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
});

test('Revoked before Granted leaves the client idle', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliver((await find(h, 'Acquire')).id);
  await h.expire();
  await h.deliver((await find(h, 'Revoked')).id);
  assert.equal((await h.client('c0')).status, 'requesting');
  await h.deliver((await find(h, 'Granted')).id);
  assert.equal((await h.client('c0')).status, 'idle');
  // a later, newer grant is held
  await h.acquire('c0'); await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 2, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 2, writes: 0 });
});

test('one write per grant', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0'); await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  assert.deepEqual(await h.write('c0'), { ok: true });
  await h.deliver((await find(h, 'Write')).id);
  assert.ok(await find(h, 'WriteRefused', 'c0'));
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.equal((await h.lease()).writes, 1);
  // a new grant allows a new write
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  await h.write('c1');
  await h.deliver((await find(h, 'Write')).id);
  assert.ok(await find(h, 'WriteDone', 'c1'));
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 2 });
});

test('a refused stale write does not use up the new grant', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0');
  await h.expire(); await h.deliver((await find(h, 'Revoked')).id);
  await h.acquire('c1'); await h.deliver((await find(h, 'Acquire')).id);
  await h.deliver((await find(h, 'Write')).id); // stale token 1
  assert.ok(await find(h, 'WriteRefused', 'c0'));
  await h.deliverAll();
  await h.write('c1'); await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 1 });
});

test('release waits for Released', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.deepEqual(await h.client('c0'), { status: 'releasing', token: 1, writing: false });
  for (const cmd of ['acquire', 'release', 'write']) assert.equal((await h[cmd]('c0')).ok, false);
  await h.deliver((await find(h, 'Release')).id);
  const r = await find(h, 'Released', 'c0');
  assert.deepEqual([r.from, r.data], ['lease', {}]);
  assert.equal((await h.client('c0')).status, 'releasing');
  assert.equal((await h.lease()).holder, null);
  await h.deliver(r.id);
  assert.equal((await h.client('c0')).status, 'idle');
  assert.deepEqual(await h.acquire('c0'), { ok: true });
});

test('ignored release is still answered; releasing client ignores Revoked', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.release('c0');
  await h.expire();
  await h.deliver((await find(h, 'Revoked')).id);
  assert.deepEqual(await h.client('c0'), { status: 'releasing', token: 1, writing: false });
  await h.deliver((await find(h, 'Release')).id); // stale: service has no holder
  assert.ok(await find(h, 'Released', 'c0'));
  await h.deliverAll();
  assert.equal((await h.client('c0')).status, 'idle');
