const without = (net, i) => net.filter((_, j) => j !== i);
const isClient = (c) => CLIENTS.includes(c);

const clientSchema = { client: { type: 'string', required: true } };
const clientDomain = [{ client: 'c0' }, { client: 'c1' }, { client: 'c2' }];
const actions = {
  acquire: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  release: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  write: { action: (data = {}) => ({ ...data }), schema: clientSchema, domain: clientDomain },
  expire: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
  deliver: {
    action: (data = {}) => ({ ...data }),
    schema: { i: { type: 'number', required: true } },
    domain: Array.from({ length: MAX_NET }, (_, i) => ({ i })),
  },
};

const acceptors = {
  acquire: (model) => ({ client }, { reject, next, unchanged }) => {
    if (!isClient(client)) return reject('unknown client');
    if (model[client].status !== 'idle') return reject('client not idle');
