    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => (s[c].status === 'holding') === (s.holder === c)),
  },
  { name: 'grant-limit', pred: (s) => s.token >= 0 && s.token <= 2 },
  { name: 'write-limit', pred: (s) => s.writes >= 0 && s.writes <= 2 },
  { name: 'writes-need-grants', pred: (s) => s.writes === 0 || s.token > 0 },
  { name: 'at-most-one-write-per-grant', pred: (s) => s.writes <= s.token },
  { name: 'holder-is-a-client', pred: (s) => s.holder === null || CLIENTS.includes(s.holder) },
  { name: 'client-token-not-ahead', pred: (s) => CLIENTS.every((c) => s[c].token <= s.token && s[c].revoked <= s.token) },
  // per client: one request/release exchange and one write exchange; plus at most 2 Revokeds
  { name: 'network-bounded', pred: (s) => s.net.length <= 6 },
  {
    name: 'quiescent-no-pending-exchange',
    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => (s[c].status === 'idle' || s[c].status === 'holding') && !s[c].writing),
  },
  {
    name: 'abandoning-awaits-answer',
    pred: (s) => CLIENTS.every((c) => s[c].status !== 'abandoning'
      || s.net.some((m) => (m.action === 'Acquire' && m.from === c) || ((m.action === 'Granted' || m.action === 'Denied') && m.to === c))),
  },
  {
    name: 'releasing-awaits-answer',
    pred: (s) => CLIENTS.every((c) => s[c].status !== 'releasing'
      || s.net.some((m) => (m.action === 'Release' && m.from === c) || (m.action === 'Released' && m.to === c))),
  },
  {
    name: 'holding-not-revoked',
    pred: (s) => CLIENTS.every((c) => s[c].status !== 'holding' || s[c].token > s[c].revoked),
  },
];

export const transitionInvariants = [
  {
    name: 'writes-only-from-current-holder',
    pred: (pre, action, data, post) => {
      if (post.writes === pre.writes) return true;
      if (action !== 'deliver' || post.writes !== pre.writes + 1) return false;
      const m = pre.net[data.i];
      return m.action === 'Write' && m.data.from === pre.holder && m.data.token === pre.token;
    },
  },
  {
    // the rule itself: a write is taken only if none was taken since the last grant
    name: 'one-write-per-grant',
    pred: (pre, _a, _d, post) => post.writes === pre.writes || (!pre.wrote && post.wrote),
  },
  {
    name: 'release-always-answered',
    pred: (pre, action, data, post) => {
      if (action !== 'deliver' || !pre.net[data.i] || pre.net[data.i].action !== 'Release') return true;
      const from = pre.net[data.i].from;
      const count = (s) => s.net.filter((m) => m.action === 'Released' && m.to === from).length;
      return count(post) === count(pre) + 1;
    },
  },
  {
    name: 'releasing-ignores-revoked',
    pred: (pre, action, data, post) => {
      const m = action === 'deliver' ? pre.net[data.i] : null;
      if (!m || m.action !== 'Revoked' || pre[m.to].status !== 'releasing') return true;
      return JSON.stringify(post[m.to]) === JSON.stringify(pre[m.to]);
    },
  },
  {
    name: 'tokens-only-go-up',
    pred: (pre, _a, _d, post) => post.token === pre.token || post.token === pre.token + 1,
  },
  {
    name: 'grant-goes-to-requester',
    pred: (pre, action, data, post) => {
      if (post.token === pre.token) return true;
      const m = pre.net[data.i];
      return action === 'deliver' && m.action === 'Acquire' && post.holder === m.data.from && pre.holder === null;
    },
  },
];

// Captures NDJSON trace windows {pre, action, data, post} from src/host.impl.ts,
// in the shape of spec/lease.cjs: in-flight messages without ids, sorted
// canonically, and `deliver({ i })` naming the i-th message of that order.
// Usage: node spec/capture.mjs [outDir]
import { mkdirSync, writeFileSync } from 'node:fs';
import { createSystem } from '../src/host.impl.ts';

const outDir = process.argv[2] ?? 'spec/traces';
mkdirSync(outDir, { recursive: true });

const key = (m) => JSON.stringify([m.to, m.action, m.from, m.data.from ?? null, m.data.token ?? null]);
const sortedNet = (net) => [...net].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));

function snapshot(sys) {
  const s = sys.state;
  const net = sortedNet(s.net).map(({ from, to, action, data }) => ({ from, to, action, data: { ...data } }));
  return { holder: s.service.holder, token: s.service.token, writes: s.service.writes, wrote: s.service.wroteSinceGrant, c0: { ...s.clients.c0 }, c1: { ...s.clients.c1 }, net };
}

function step(sys, windows, action, data) {
  const pre = snapshot(sys);
  if (action === 'deliver') {
    const m = sortedNet(sys.state.net)[data.i];
    if (m) sys.deliver(m.id);
  } else if (action === 'expire') sys.expire();
  else sys[action](data.client);
  windows.push({ pre, action, data, post: snapshot(sys) });
}

const save = (name, windows) => writeFileSync(`${outDir}/${name}.ndjson`, windows.map((w) => JSON.stringify(w)).join('\n') + '\n');

// Scripted scenarios.
const scripted = {
  happy: [['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['release', 'c0'], ['deliver', 0], ['deliver', 0]],
  releasing: [['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['release', 'c0'], ['acquire', 'c0'], ['write', 'c0'], ['release', 'c0'], ['expire'],
    ['deliver', 1], ['deliver', 0], ['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['acquire', 'c0'], ['deliver', 0], ['deliver', 0]],
  revokedBeforeGranted: [['acquire', 'c0'], ['deliver', 0], ['expire'], ['deliver', 1], ['deliver', 0], ['acquire', 'c0'], ['deliver', 0], ['deliver', 0]],
  staleWrite: [['acquire', 'c1'], ['deliver', 0], ['deliver', 0], ['write', 'c1'], ['expire'], ['deliver', 1], ['deliver', 0], ['deliver', 0], ['write', 'c1']],
  limits: [['acquire', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['write', 'c0'], ['deliver', 0], ['deliver', 0],
    ['write', 'c0'], ['deliver', 0], ['deliver', 0], ['release', 'c0'], ['deliver', 0], ['acquire', 'c1'], ['deliver', 0], ['deliver', 0], ['release', 'c1'], ['deliver', 0],
    ['acquire', 'c0'], ['deliver', 0], ['deliver', 0]],
  refusals: [['acquire', 'c2'], ['release', 'c0'], ['write', 'c0'], ['expire'], ['deliver', 3], ['acquire', 'c0'], ['acquire', 'c0'], ['deliver', 0], ['acquire', 'c1'], ['deliver', 1], ['deliver', 0], ['deliver', 0]],
};
for (const [name, cmds] of Object.entries(scripted)) {
  const sys = createSystem();
  const windows = [];
  for (const [action, arg] of cmds) {
    const data = action === 'deliver' ? { i: arg } : action === 'expire' ? {} : { client: arg };
    step(sys, windows, action, data);
  }
  save(name, windows);
}

// Random schedules (deterministic LCG).
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
for (let run = 0; run < 40; run++) {
  const sys = createSystem();
  const windows = [];
  for (let k = 0; k < 40; k++) {
    const r = rnd(10);
    const client = ['c0', 'c1', 'c0', 'c1', 'c2'][rnd(5)];
    if (r === 0) step(sys, windows, 'acquire', { client });
    else if (r === 1) step(sys, windows, 'release', { client });
    else if (r === 2) step(sys, windows, 'write', { client });
    else if (r === 3) step(sys, windows, 'expire', {});
    else step(sys, windows, 'deliver', { i: rnd(Math.max(1, sys.state.net.length + (r === 9 ? 1 : 0))) });
  }
  save(`random-${String(run).padStart(2, '0')}`, windows);
}
console.log(`traces written to ${outDir}`);

