// Negative control: seed known bugs into copies of spec/lease.cjs and confirm the
// invariants catch each one. Usage: node spec/negative-control.mjs [mutant ...]
import { readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { check, loadSpec } from '../tools/polygraph/scripts/check.mjs';
import * as invariants from './invariants.mjs';

const src = readFileSync('spec/lease.cjs', 'utf-8').replace(
  "'../tools/polygraph/scripts/vendor/sam-pattern.cjs'",
  JSON.stringify(resolve('tools/polygraph/scripts/vendor/sam-pattern.cjs')),
);
const contract = JSON.parse(readFileSync('spec/contract.json', 'utf-8'));

const mutants = {
  'no-revoked-memory': ["status: t <= c.revoked ? 'idle' : 'holding'", "status: 'holding'"],
  'write-ignores-token': ["m.data.token === model.token", 'true'],
  'many-writes-per-grant': ['current && !model.wrote && model.writes', 'current && model.writes'],
  'releasing-honors-revoked': ["if (c.status === 'releasing') {", "if (false) {"],
  'release-unanswered': ["next.net = withMsg(rest, msg(SERVICE, from, 'Released', {}));", 'next.net = rest;'],
  'release-ignores-holder': ["if (current) next.holder = null;", 'next.holder = null;'],
};

let failed = 0;
const only = process.argv.slice(2);
for (const [name, [from, to]] of Object.entries(mutants)) {
  if (only.length && !only.includes(name)) continue;
  if (!src.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  const file = join(tmpdir(), `lease-mutant-${name}.cjs`);
  writeFileSync(file, src.replace(from, to));
  const r = check({ specModule: loadSpec(file), contract, invariants, maxStates: 200000 });
  const caught = (r.violations || []).map((v) => v.name ?? v.invariant);
  console.log(`${name}: ${caught.length ? 'caught by ' + caught.join(', ') : 'NOT CAUGHT'}${r.error ? ' (error: ' + r.error + ')' : ''}`);
  if (!caught.length) failed++;
}
process.exit(failed ? 1 : 0);
